package com.vms.vendorcontractmanagement.config; import com.vms.vendorcontractmanagement.repository.*; import jakarta.servlet.*; import jakarta.servlet.http.*; import lombok.*; import org.springframework.context.annotation.*; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.method.configuration.*; import org.springframework.security.config.annotation.web.builders.*; import org.springframework.security.config.http.*; import org.springframework.security.core.*; import org.springframework.security.core.authority.*; import org.springframework.security.core.context.*; import org.springframework.security.crypto.bcrypt.*; import org.springframework.security.crypto.password.*; import org.springframework.security.web.*; import org.springframework.security.web.authentication.*; import org.springframework.web.cors.*; import org.springframework.web.filter.OncePerRequestFilter; import java.io.*; import java.util.*;
@Configuration @EnableMethodSecurity @RequiredArgsConstructor public class SecurityConfig { final JwtService jwt; final UserRepository users; @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain security(HttpSecurity h) throws Exception {return h.csrf(x->x.disable()).cors(x->{}).sessionManagement(x->x.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(x->x.requestMatchers("/api/auth/**","/swagger-ui/**","/v3/api-docs/**","/api/health").permitAll().anyRequest().authenticated()).addFilterBefore(new JwtFilter(jwt,users),UsernamePasswordAuthenticationFilter.class).build();} @Bean CorsConfigurationSource cors(@org.springframework.beans.factory.annotation.Value("${app.cors.allowed-origins}") String origins){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(Arrays.asList(origins.split(",")));c.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;} }
@RequiredArgsConstructor class JwtFilter extends OncePerRequestFilter { final JwtService jwt; final UserRepository users; @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws ServletException,IOException {String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{String email=jwt.claims(h.substring(7)).getSubject();users.findByEmail(email).filter(u->u.getActive()).ifPresent(u->{Authentication a=new UsernamePasswordAuthenticationToken(email,null,List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole().getName())));SecurityContextHolder.getContext().setAuthentication(a);});}catch(Exception ignored){}c.doFilter(r,p);} }
